import java.util.*;

public class Main {
    public static void main(String[] args) {
        InventoryService inventory = new InventoryService();
        inventory.addWarehouse("product-1", "warehouse-east", 5);
        inventory.addWarehouse("product-1", "warehouse-west", 3);

        // Customer A reserves 4 units: warehouse-east has enough (5 >= 4).
        ReservationResult resultA = inventory.reserveForCart("product-1", 4, 0, 900000);
        System.out.println("Customer A reserves 4 units: " + resultA);

        // Customer B reserves 3 units: warehouse-east now only has 1 left (insufficient),
        // falls through to warehouse-west, which has exactly enough (3 >= 3).
        ReservationResult resultB = inventory.reserveForCart("product-1", 3, 100, 900000);
        System.out.println("Customer B reserves 3 units: " + resultB);

        // Customer C tries to reserve 2 units: warehouse-east has 1, warehouse-west has 0. Out of stock.
        ReservationResult resultC = inventory.reserveForCart("product-1", 2, 200, 900000);
        System.out.println("Customer C tries to reserve 2 units (should be out of stock): " + resultC);

        // Time passes past Customer A's hold expiry (900000) but NOT yet past Customer B's (900100),
        // since they never checked out either, only A's window has actually closed.
        inventory.expireHoldsBefore(900050);
        System.out.println("Combined available stock after A's hold expires (B's hold is still active): " + inventory.combinedAvailableStock("product-1"));

        // Customer C tries again, now that A's released stock is available.
        ReservationResult resultC2 = inventory.reserveForCart("product-1", 2, 900060, 900000);
        System.out.println("Customer C retries after A's expiry: " + resultC2);

        // Customer B completes checkout while their hold is still genuinely active: converts to a permanent sale.
        inventory.completeCheckout(resultB.holdId);
        System.out.println("Combined available stock after B's checkout (should not restore B's units): " + inventory.combinedAvailableStock("product-1"));
    }
}

// The outcome of a reservation attempt: whether it succeeded, which
// warehouse fulfilled it, and the hold id created for a successful reservation.
class ReservationResult {
    boolean success;
    String warehouseId;
    String holdId;

    ReservationResult(boolean success, String warehouseId, String holdId) {
        this.success = success;
        this.warehouseId = warehouseId;
        this.holdId = holdId;
    }

    public String toString() {
        return success ? ("RESERVED from " + warehouseId + ", hold=" + holdId) : "OUT_OF_STOCK";
    }
}

// One warehouse's stock for one product.
class WarehouseStock {
    String warehouseId;
    int availableStock;

    WarehouseStock(String warehouseId, int availableStock) {
        this.warehouseId = warehouseId;
        this.availableStock = availableStock;
    }
}

// A time-limited cart hold: a reserved quantity from a specific warehouse,
// expiring automatically if checkout is never completed.
class CartHold {
    String productId;
    String warehouseId;
    int quantity;
    long expiresAt;

    CartHold(String productId, String warehouseId, int quantity, long expiresAt) {
        this.productId = productId;
        this.warehouseId = warehouseId;
        this.quantity = quantity;
        this.expiresAt = expiresAt;
    }
}

// Manages multi-warehouse inventory reservation with time-limited cart holds:
// a reservation tries candidate warehouses in order until one has enough
// stock, and an unclaimed hold's stock is released back once it expires.
class InventoryService {
    private final Map<String, List<WarehouseStock>> warehousesByProduct = new LinkedHashMap<>();
    private final Map<String, CartHold> activeHolds = new LinkedHashMap<>();
    private int nextHoldId = 1;

    void addWarehouse(String productId, String warehouseId, int stock) {
        warehousesByProduct.computeIfAbsent(productId, id -> new ArrayList<>()).add(new WarehouseStock(warehouseId, stock));
    }

    ReservationResult reserveForCart(String productId, int quantity, long now, long holdDurationMillis) {
        for (WarehouseStock warehouse : warehousesByProduct.get(productId)) {
            if (warehouse.availableStock >= quantity) {
                warehouse.availableStock -= quantity; // reserve atomically from this warehouse
                String holdId = "hold-" + (nextHoldId++);
                activeHolds.put(holdId, new CartHold(productId, warehouse.warehouseId, quantity, now + holdDurationMillis));
                return new ReservationResult(true, warehouse.warehouseId, holdId);
            }
        }
        return new ReservationResult(false, null, null); // no warehouse had enough, out of stock
    }

    // Releases every hold whose expiry has already passed, returning their stock.
    void expireHoldsBefore(long now) {
        List<String> toRelease = new ArrayList<>();
        for (Map.Entry<String, CartHold> entry : activeHolds.entrySet()) {
            if (entry.getValue().expiresAt <= now) toRelease.add(entry.getKey());
        }
        for (String holdId : toRelease) {
            CartHold hold = activeHolds.remove(holdId);
            for (WarehouseStock warehouse : warehousesByProduct.get(hold.productId)) {
                if (warehouse.warehouseId.equals(hold.warehouseId)) {
                    warehouse.availableStock += hold.quantity; // released back, available again
                }
            }
        }
    }

    // Converts a hold into a permanent sale: the hold record is removed, but
    // its reserved stock is never restored, since it has genuinely been sold.
    void completeCheckout(String holdId) {
        activeHolds.remove(holdId);
    }

    int combinedAvailableStock(String productId) {
        int total = 0;
        for (WarehouseStock warehouse : warehousesByProduct.get(productId)) total += warehouse.availableStock;
        return total;
    }
}

