class ReservationResult:
    # The outcome of a reservation attempt: whether it succeeded, which
    # warehouse fulfilled it, and the hold id created for a successful reservation.
    def __init__(self, success, warehouse_id, hold_id):
        self.success = success
        self.warehouse_id = warehouse_id
        self.hold_id = hold_id

    def __repr__(self):
        return f"RESERVED from {self.warehouse_id}, hold={self.hold_id}" if self.success else "OUT_OF_STOCK"


class WarehouseStock:
    # One warehouse's stock for one product.
    def __init__(self, warehouse_id, available_stock):
        self.warehouse_id = warehouse_id
        self.available_stock = available_stock


class CartHold:
    # A time-limited cart hold: a reserved quantity from a specific
    # warehouse, expiring automatically if checkout is never completed.
    def __init__(self, product_id, warehouse_id, quantity, expires_at):
        self.product_id = product_id
        self.warehouse_id = warehouse_id
        self.quantity = quantity
        self.expires_at = expires_at


class InventoryService:
    # Manages multi-warehouse inventory reservation with time-limited cart
    # holds: a reservation tries candidate warehouses in order until one has
    # enough stock, and an unclaimed hold's stock is released back once it expires.
    def __init__(self):
        self.warehouses_by_product = {}
        self.active_holds = {}
        self.next_hold_id = 1

    def add_warehouse(self, product_id, warehouse_id, stock):
        self.warehouses_by_product.setdefault(product_id, []).append(WarehouseStock(warehouse_id, stock))

    def reserve_for_cart(self, product_id, quantity, now, hold_duration_millis):
        for warehouse in self.warehouses_by_product[product_id]:
            if warehouse.available_stock >= quantity:
                warehouse.available_stock -= quantity  # reserve atomically from this warehouse
                hold_id = f"hold-{self.next_hold_id}"
                self.next_hold_id += 1
                self.active_holds[hold_id] = CartHold(product_id, warehouse.warehouse_id, quantity, now + hold_duration_millis)
                return ReservationResult(True, warehouse.warehouse_id, hold_id)
        return ReservationResult(False, None, None)  # no warehouse had enough, out of stock

    def expire_holds_before(self, now):
        to_release = [hold_id for hold_id, hold in self.active_holds.items() if hold.expires_at <= now]
        for hold_id in to_release:
            hold = self.active_holds.pop(hold_id)
            for warehouse in self.warehouses_by_product[hold.product_id]:
                if warehouse.warehouse_id == hold.warehouse_id:
                    warehouse.available_stock += hold.quantity  # released back, available again

    def complete_checkout(self, hold_id):
        self.active_holds.pop(hold_id, None)

    def combined_available_stock(self, product_id):
        return sum(w.available_stock for w in self.warehouses_by_product[product_id])


def main():
    inventory = InventoryService()
    inventory.add_warehouse("product-1", "warehouse-east", 5)
    inventory.add_warehouse("product-1", "warehouse-west", 3)

    # Customer A reserves 4 units: warehouse-east has enough (5 >= 4).
    result_a = inventory.reserve_for_cart("product-1", 4, 0, 900000)
    print("Customer A reserves 4 units:", result_a)

    # Customer B reserves 3 units: warehouse-east now only has 1 left (insufficient),
    # falls through to warehouse-west, which has exactly enough (3 >= 3).
    result_b = inventory.reserve_for_cart("product-1", 3, 100, 900000)
    print("Customer B reserves 3 units:", result_b)

    # Customer C tries to reserve 2 units: warehouse-east has 1, warehouse-west has 0. Out of stock.
    result_c = inventory.reserve_for_cart("product-1", 2, 200, 900000)
    print("Customer C tries to reserve 2 units (should be out of stock):", result_c)

    # Time passes past Customer A's hold expiry (900000) but NOT yet past Customer B's (900100),
    # since they never checked out either, only A's window has actually closed.
    inventory.expire_holds_before(900050)
    print("Combined available stock after A's hold expires (B's hold is still active):", inventory.combined_available_stock("product-1"))

    # Customer C tries again, now that A's released stock is available.
    result_c2 = inventory.reserve_for_cart("product-1", 2, 900060, 900000)
    print("Customer C retries after A's expiry:", result_c2)

    # Customer B completes checkout while their hold is still genuinely active: converts to a permanent sale.
    inventory.complete_checkout(result_b.hold_id)
    print("Combined available stock after B's checkout (should not restore B's units):", inventory.combined_available_stock("product-1"))


