struct ReservationResult {
    bool success;
    string warehouseId;
    string holdId;
};

ostream& operator<<(ostream& os, const ReservationResult& r) {
    if (r.success) os << "RESERVED from " << r.warehouseId << ", hold=" << r.holdId;
    else os << "OUT_OF_STOCK";
    return os;
