public:
    void addWarehouse(const string& productId, const string& warehouseId, int stock) {
        warehousesByProduct[productId].push_back({warehouseId, stock});
    }

    ReservationResult reserveForCart(const string& productId, int quantity, long now, long holdDurationMillis) {
        for (auto& warehouse : warehousesByProduct[productId]) {
            if (warehouse.availableStock >= quantity) {
                warehouse.availableStock -= quantity; // reserve atomically from this warehouse
                string holdId = "hold-" + to_string(nextHoldId++);
                activeHolds[holdId] = {productId, warehouse.warehouseId, quantity, now + holdDurationMillis};
                return {true, warehouse.warehouseId, holdId};
            }
        }
        return {false, "", ""}; // no warehouse had enough, out of stock
    }

    void expireHoldsBefore(long now) {
        vector<string> toRelease;
        for (const auto& entry : activeHolds) {
            if (entry.second.expiresAt <= now) toRelease.push_back(entry.first);
        }
        for (const auto& holdId : toRelease) {
            CartHold hold = activeHolds[holdId];
            activeHolds.erase(holdId);
            for (auto& warehouse : warehousesByProduct[hold.productId]) {
                if (warehouse.warehouseId == hold.warehouseId) {
                    warehouse.availableStock += hold.quantity; // released back, available again
                }
            }
        }
    }

    void completeCheckout(const string& holdId) {
        activeHolds.erase(holdId);
    }

    int combinedAvailableStock(const string& productId) {
        int total = 0;
        for (const auto& warehouse : warehousesByProduct[productId]) total += warehouse.availableStock;
        return total;
    }

private:
    map<string, vector<WarehouseStock>> warehousesByProduct;
    map<string, CartHold> activeHolds;
    int nextHoldId = 1;
};

