    // falls through to warehouse-west, which has exactly enough (3 >= 3).
    ReservationResult resultB = inventory.reserveForCart("product-1", 3, 100, 900000);
    cout << "Customer B reserves 3 units: " << resultB << endl;

    // Customer C tries to reserve 2 units: warehouse-east has 1, warehouse-west has 0. Out of stock.
    ReservationResult resultC = inventory.reserveForCart("product-1", 2, 200, 900000);
    cout << "Customer C tries to reserve 2 units (should be out of stock): " << resultC << endl;

    // Time passes past Customer A's hold expiry (900000) but NOT yet past Customer B's (900100),
    // since they never checked out either, only A's window has actually closed.
    inventory.expireHoldsBefore(900050);
    cout << "Combined available stock after A's hold expires (B's hold is still active): " << inventory.combinedAvailableStock("product-1") << endl;

    // Customer C tries again, now that A's released stock is available.
    ReservationResult resultC2 = inventory.reserveForCart("product-1", 2, 900060, 900000);
    cout << "Customer C retries after A's expiry: " << resultC2 << endl;

